      <li>\u0939\u093E\u0930\u094D\u0921\u0938\u094D\u0915\u0947\u092A\u093F\u0902\u0917 \u2013 \u092A\u0924\u094D\u0925\u0930, \u0915\u0902\u0915\u094D\u0930\u0940\u091F, \u091F\u093E\u0907\u0932\u0947\u0902</li>
